pub struct LlmClients {
    fast: Box<dyn LlmClient>,
    mid: Box<dyn LlmClient>,
    strong: Box<dyn LlmClient>,
}

impl LlmClients {
    pub fn new(
        fast: Box<dyn LlmClient>,
        mid: Box<dyn LlmClient>,
        strong: Box<dyn LlmClient>,
    ) -> Self {
        Self { fast, mid, strong }
    }

    fn client(&self, tier: Tier) -> &dyn LlmClient {
        match tier {
