#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RunStatus {
    Done,
    MaxSteps,
}

#[derive(Clone, Debug)]
pub struct RunResult {
    pub status: RunStatus,
    pub final_action: Action,
    pub steps: Vec<StepRecord>,
    pub final_observation: Observation,
}

#[derive(Debug)]
pub enum AgentError {
